import React, { useState } from 'react';
import { Stat, PageTitle, Field, Modal, Status, Empty } from '../../components/common';
import './PropertiesPage.css';

export default function PropertiesPage({properties,onAdd,money}) { return <div className="module-page module-page--properties"><PageTitle eyebrow="INVENTORY" title="Property inventory" subtitle="Keep listings, availability and pricing in sync with your team." actions={onAdd ? <button className="btn primary" onClick={onAdd}>＋ Add property</button> : null}/><div className="property-grid">{properties.map((p,i)=><div className="panel property-card" key={p.id}><div className={`property-art art-${i%3}`}><span className="property-type">{p.type}</span><span className="property-status">{p.status}</span><div className="building-illustration"><i/><i/><i/><i/><i/><i/><i/><i/><i/></div></div><div className="property-content"><small>{p.id}</small><h3>{p.name}</h3><p>⌖ {p.location}</p><div className="property-bottom"><b>{money(p.price)}</b><button className="text-action" onClick={()=>navigator.clipboard?.writeText(`${p.name} — ${p.location} — ${money(p.price)}`)}>Copy details ↗</button></div></div></div>)}</div>{!properties.length&&<Empty title="No inventory yet" desc="Add your first property to match with buyer requirements."/>}</div>; }
